<script setup>defineProps({state:Object})</script><template><div v-if="state.totalPages>1" class="flex justify-center items-center gap-5 py-6 text-xs text-[#1E325A]"><button :disabled="state.busy||!state.page" class="rounded-full border px-4 py-2 bg-white disabled:opacity-40" @click="state.load(state.page-1)">← Trước</button><span>Trang {{state.page+1}} / {{state.totalPages}} · {{state.totalElements}} kết quả</span><button :disabled="state.busy||state.page+1>=state.totalPages" class="rounded-full border px-4 py-2 bg-white disabled:opacity-40" @click="state.load(state.page+1)">Sau →</button></div></template>